#!/usr/bin/env python3
"""Import the new NIA/FMR workbooks into the report pages and add GEOAGRI lookup."""
from __future__ import annotations
import glob, html, json, posixpath, re, shutil, zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'analysis_output'
STATIC=ROOT.parent/'open-data-visualization/static/nep-preview'
NS={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

def workbook_rows(path: Path):
    with zipfile.ZipFile(path) as z:
        wb=ET.fromstring(z.read('xl/workbook.xml'))
        rel=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        targets={x.attrib['Id']:x.attrib['Target'] for x in rel}
        sheet=wb.find('.//m:sheet',NS)
        root=ET.fromstring(z.read(posixpath.normpath('xl/'+targets[sheet.attrib['{'+NS['r']+'}id']])))
        strings=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            strings=[''.join(t.text or '' for t in si.findall('.//m:t',NS)) for si in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',NS)]
        for row in root.findall('.//m:sheetData/m:row',NS):
            values={}
            for cell in row.findall('m:c',NS):
                col=re.match('[A-Z]+',cell.attrib['r']).group()
                v=cell.find('m:v',NS)
                if v is not None:
                    value=v.text
                    if cell.attrib.get('t')=='s': value=strings[int(value)]
                    elif cell.attrib.get('t')=='b': value=value=='1'
                    values[col]=value
                else:
                    inline=cell.find('m:is',NS)
                    if inline is not None: values[col]=''.join(t.text or '' for t in inline.findall('.//m:t',NS))
            yield int(row.attrib['r']),values

def num(v):
    if v is None or v=='': return None
    try: return round(float(str(v).replace(',','')),2)
    except (TypeError,ValueError): return None

def extract_nia():
    path=next((ROOT/'data_sources').glob('NIA%*'))
    records=[]; context={}
    for row,d in workbook_rows(path):
        if row<8: continue
        for col,key,lower in [('B','program',['subprogram','activity','region','province']),('C','subprogram',['activity','region','province']),('D','activity',['region','province']),('E','region',['province']),('F','province',[])]:
            if d.get(col):
                for child in lower: context.pop(child,None)
                context[key]=d[col]
        title=(d.get('G') or '').strip()
        if not title: continue
        records.append({'row':row,**context,'nepTitle':title,'submissionTitle':(d.get('V') or '').strip() or None,
          'nepPesos':num(d.get('H')),'hgabPesos':num(d.get('I')),'variancePesos':num(d.get('J')),
          'submissionPesos':num(d.get('W')),'edited':(d.get('X') or '').strip() or None,
          'nepProjects':num(d.get('M')),'hgabProjects':num(d.get('N')),'justification':(d.get('Y') or '').strip() or None})
    return {'source':'NIA FY 2027 Irrigation Program workbook · sheet DETAILS 2027 · heading: NEP AND GAB / FOR SUBMISSION TO SENATE','records':records}

def extract_fmr():
    path=next((ROOT/'data_sources').glob('Working Draft*'))
    records=[]
    for row,d in workbook_rows(path):
        control=(d.get('A') or '').strip()
        if not control or not re.match(r'R\d+[-A-Z0-9]*',control): continue
        records.append({'row':row,'control':control,'from':(d.get('B') or '').strip() or None,
          'to':(d.get('C') or '').strip() or None,'amountPesos':num(d.get('D')),
          'increasePesos':num(d.get('E')),'decreasePesos':num(d.get('F')),
          'proposedAmountPesos':num(d.get('G')),'remarks':(d.get('H') or '').strip() or None})
    return {'source':'Working Draft as of Nov 5 · sheet Draft · DA FMR proposed adjustments','records':records}

def json_script(obj):
    return json.dumps(obj,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')

