def replace_once(text,old,new,label):
    if old not in text: raise RuntimeError(f'Missing insertion point for {label}')
    return text.replace(old,new,1)

def main():
    nia=extract_nia(); fmr=extract_fmr()
    (OUT/'nia-submission-workbook.json').write_text(json.dumps(nia,ensure_ascii=False,indent=2)+'\n')
    (OUT/'fmr-nov5-working-draft.json').write_text(json.dumps(fmr,ensure_ascii=False,indent=2)+'\n')
    niafile=OUT/'nia.html'; ntext=niafile.read_text()
    start=ntext.find('<section id="nia-nep-source-note"')
    if start<0: start=ntext.find('<section class="source-ledger" id="nia-submission-workbook"')
    end=ntext.find('<section id="nia-data-quality-flag"',start)
    if start<0 or end<0: raise RuntimeError('NIA workbook note insertion markers are missing')
    ntext=ntext[:start]+NIA_HTML+NIA_JS.replace('__NIA_JSON__',json_script(nia))+ntext[end:]
    ntext=re.sub(r'<style id="nia-workbook-data-style">.*?</style>','',ntext,count=1,flags=re.S)
    ntext=replace_once(ntext,'</head>',NIA_CSS+'</head>','NIA stylesheet')
    niafile.write_text(ntext)
    fmrfile=OUT/'fmr.html'; ftext=fmrfile.read_text()
    add=FMR_HTML+FMR_JS.replace('__FMR_JSON__',json_script(fmr))+'</section>'
    oldstart=ftext.find('<section class="fmr-new-ledger" id="fmr-new-source-data">')
    if oldstart>=0:
        oldend=ftext.find('<section class="card fmr-manual-red"',oldstart)
        if oldend<0: raise RuntimeError('FMR existing source table end marker is missing')
        ftext=ftext[:oldstart]+add+ftext[oldend:]
    else:
        anchor='</section><section class="card fmr-manual-red"'
        ftext=replace_once(ftext,anchor,'</section>'+add+'<section class="card fmr-manual-red"','FMR source data')
    ftext=re.sub(r'<style id="fmr-new-data-style">.*?</style>','',ftext,count=1,flags=re.S)
    ftext=replace_once(ftext,'</head>',FMR_CSS+'</head>','FMR stylesheet')
    fmrfile.write_text(ftext)
    STATIC.mkdir(parents=True,exist_ok=True)
    for name in ['nia.html','fmr.html']:
        shutil.copy2(OUT/name,STATIC/name)
    for name in ['nia-submission-workbook.json','fmr-nov5-working-draft.json']:
        shutil.copy2(OUT/name,STATIC/name)
    print(json.dumps({'nia_project_rows':len(nia['records']),'fmr_control_rows':len(fmr['records']),'output_pages':[str(OUT/'nia.html'),str(OUT/'fmr.html'),str(STATIC/'nia.html'),str(STATIC/'fmr.html')]},indent=2))

if __name__=='__main__': main()
